import React, {Component} from 'react';
import {Image, StyleSheet, View} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import style from './HomeStyles';
// import SwipeCards from 'react-native-swipe-cards';
import Swiper from 'react-native-deck-swiper'
import firebaseApp from '../Firebase.js';
import Sound from 'react-native-sound';

const swipeSound = new Sound('pageflip.mp3', Sound.MAIN_BUNDLE);



class FlashCard extends Component<{}> {
  renderCard = card => {
    return (
      <View style={style.card}>
        <Image
          style={{
            height: '100%',
            width: '100%',
            position: 'absolute',
            top: 0,
            left: 0,
          }}
          resizeMode={'cover'}
          source={{uri: card}}
        />
      </View>
    )
  };
  onSwipedAllCards = () => {
    this.setState({
      swipedAllCards: true
    });
   firebaseApp.analytics().logEvent('SwipedAllCards');

  };
  swipeBack = () => {
    if (!this.state.isSwipingBack) {
      this.setIsSwipingBack(true, () => {
        this.swiper.swipeBack(() => {
          this.setIsSwipingBack(false)
        });
      })
    }
  };
  setIsSwipingBack = (isSwipingBack, cb) => {
    this.setState(
      {
        isSwipingBack: isSwipingBack
      },
      cb
    )
  };
  

  constructor(props) {
    super(props);
    this.state = {
      cards: ['1', '2', '3'],
      swipedAllCards: false,
      swipeDirection: '',
      isSwipingBack: false,
      cardIndex: 0,
      cardList: [],
    }
  }

  render() {
    const {flashCards} = this.props;
    return (
      <View style={style.flashCard}>
        {
          flashCards.length && !this.state.swipedAllCards
            ? <Swiper
              ref={swiper => {
                this.swiper = swiper
              }}
              onSwiped={() => {swipeSound.play();}}
              onSwipedRight={this.swipeRight}
              //onTapCard={this.swipeLeft}
              onSwipedLeft={this.swipeLeft}
              cards={flashCards}
              cardIndex={this.state.cardIndex}
              cardVerticalMargin={0}
              cardHorizontalMargin={0}
              renderCard={this.renderCard}
              onSwipedAll={this.onSwipedAllCards}
              stackSize={3}
              stackSeparation={15}
              animateOverlayLabelsOpacity
              animateCardOpacity
            />
            : <Image
              style={{
                height: '100%',
                width: '100%',
                position: 'absolute',
                top: 0,
                left: 0,
              }}
              resizeMode={'cover'}
              source={{uri: 'data:image/jpeg;base64,'}}
            />
        }
      </View>
    )
  }

}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    height: 400,
    width: 400,
    backgroundColor: '#F5FCFF'
  },
  card: {
    flex: 1,
    borderRadius: 4,
    borderWidth: 2,
    borderColor: '#E8E8E8',
    justifyContent: 'center',
    backgroundColor: 'pink'
  },
  text: {
    textAlign: 'center',
    fontSize: 50,
    backgroundColor: 'transparent'
  },
  done: {
    textAlign: 'center',
    fontSize: 30,
    color: 'white',
    backgroundColor: 'transparent'
  }
});

const mapStateToProps = state => ({});
const mapDispatchToProps = dispatch => bindActionCreators({}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(FlashCard);